/**
 * Performs a deep equality check between two values by recursively comparing all properties.
 * Handles primitives, arrays, nested objects, `null`, and `undefined` values.
 * @param a - The first value to compare.
 * @param b - The second value to compare.
 * @returns `true` if both values are deeply equal, `false` otherwise.
 */
export const isObjectEqual = (a: unknown, b: unknown): boolean => {
    if (a === b) return true;
    if (a === null || a === undefined || b === null || b === undefined) return false;
    if (typeof a !== "object" || typeof b !== "object") return false;

    if (Array.isArray(a) !== Array.isArray(b)) return false;
    if (Array.isArray(a) && Array.isArray(b)) {
        if (a.length !== b.length) return false;
        return a.every((val, i) => isObjectEqual(val, b[i]));
    }

    const objA = a as Record<string, unknown>;
    const objB = b as Record<string, unknown>;
    const keysA = Object.keys(objA);
    const keysB = Object.keys(objB);

    if (keysA.length !== keysB.length) return false;

    return keysA.every((key) => isObjectEqual(objA[key], objB[key]));
};
